root=Path(__file__).resolve().parents[1];p=root/'fixtures/demo-full-64-b300';seed=json.loads((p/'demo-seed.json').read_text());c=seed['collections'];counts={k:len(v) for k,v in c.items()};seed['meta']['counts']=counts;seed['meta']['collection_counts']=counts;seed['meta']['dataset_id']='keel-demo-b300-64-full';seed['meta']['schema_version']='keel-mock-data/v2.4';(p/'demo-seed.json').write_text(json.dumps(seed,ensure_ascii=False,indent=2)+'\n')
